/**
 * i18n.js — Runtime strings for the static language pages.
 *
 * Every language has its own page, generated by tools/build.mjs ("/" = English, /es/, /fr/, /it/), so
 * this script no longer rewrites the page. It does two things:
 * - serves the strings JavaScript writes at runtime (menu labels, booking form messages, WhatsApp
 *   messages) from window.SITE_TRANSLATIONS, in the page language with English and Spanish fallbacks;
 * - remembers the language a visitor picks in the language switch ([data-lang-option] links), so the
 *   root page sends them to it next time (src/partials/root-redirect.html).
 * WhatsApp messages are written in messageLanguage(): the page language when the team reads it
 * (Spanish, English), otherwise English.
 * Exposes window.SiteI18n = { t, messageLanguage, getLanguage }.
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'site-lang';
  /** Languages the team reads on WhatsApp, and the one used for messages from any other page language. */
  var TEAM_LANGUAGES = ['es', 'en'];
  var TEAM_FALLBACK = 'en';
  /** Where t() looks when the requested language lacks a key. */
  var FALLBACK_LANGUAGES = ['en', 'es'];
  var dictionaries = window.SITE_TRANSLATIONS || {};
  var currentLanguage = (document.documentElement.getAttribute('lang') || TEAM_FALLBACK).slice(0, 2).toLowerCase();

  /**
   * Reads a key from one dictionary without falling back.
   * @param {string} lang - Language code.
   * @param {string} key - Translation key.
   * @returns {string|undefined} The string, or undefined when missing.
   */
  function lookup(lang, key) {
    var dictionary = dictionaries[lang];
    return dictionary && Object.prototype.hasOwnProperty.call(dictionary, key) ? dictionary[key] : undefined;
  }

  /**
   * Translates a runtime key: the requested language first, then English, then Spanish.
   * @param {string} key - Translation key.
   * @param {string} [lang] - Language to translate into (defaults to the page language).
   * @returns {string} Translated string, or the key itself if no language defines it.
   */
  function t(key, lang) {
    var languages = [lang || currentLanguage].concat(FALLBACK_LANGUAGES);
    for (var i = 0; i < languages.length; i += 1) {
      var value = lookup(languages[i], key);
      if (value !== undefined) return value;
    }
    return key;
  }

  /**
   * Language for WhatsApp messages: the team reads TEAM_LANGUAGES only, so a page shown in
   * another language (French, Italian) sends its messages in TEAM_FALLBACK (English).
   * @returns {string} "es" or "en".
   */
  function messageLanguage() {
    return TEAM_LANGUAGES.indexOf(currentLanguage) > -1 ? currentLanguage : TEAM_FALLBACK;
  }

  /**
   * Saves the visitor's explicit language choice. Storage can be unavailable (private mode,
   * blocked cookies); the link still takes them to that language, only the memory is lost.
   * @param {string} lang - Language code to remember.
   * @returns {void}
   */
  function saveChoice(lang) {
    try {
      window.localStorage.setItem(STORAGE_KEY, lang);
    } catch (error) {
      /* Storage unavailable: nothing else to do. */
    }
  }

  // Language links navigate on their own; this only remembers the choice.
  document.addEventListener('click', function (event) {
    var link = event.target.closest('[data-lang-option]');
    if (link) saveChoice(link.getAttribute('data-lang-option'));
  });

  window.SiteI18n = {
    t: t,
    messageLanguage: messageLanguage,
    getLanguage: function () { return currentLanguage; }
  };
})();
